import{b as a,O as i,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const h="/assets/image-9.ggO5SRnY.webp",c=JSON.parse('{"title":"标签管理","description":"","frontmatter":{},"headers":[],"relativePath":"git/branch/tag/index.md","filePath":"Git操作手册/3.分支管理/05.标签管理.md","lastUpdated":1783947942000}'),l={name:"git/branch/tag/index.md"};function n(p,s,d,o,k,r){return i(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="标签管理" tabindex="-1">标签管理 <a class="header-anchor" href="#标签管理" aria-label="Permalink to &quot;标签管理&quot;">​</a></h1><blockquote><p>git tag，为重要版本打一个永久标记</p></blockquote><h2 id="标签是什么" tabindex="-1">标签是什么 <a class="header-anchor" href="#标签是什么" aria-label="Permalink to &quot;标签是什么&quot;">​</a></h2><p>分支是指针，会随着提交往前移动。标签也是一个指针——但它<strong>钉在某个提交上不会动</strong>。通常用来标记版本号：</p><p><img src="'+h+`" alt="alt text"></p><p>当你发布 v2.0.0 时，打个标签。以后想回到这个版本，直接指定标签名就行——不用翻 git log 找 commit id。</p><h2 id="创建标签" tabindex="-1">创建标签 <a class="header-anchor" href="#创建标签" aria-label="Permalink to &quot;创建标签&quot;">​</a></h2><h3 id="轻量标签" tabindex="-1">轻量标签 <a class="header-anchor" href="#轻量标签" aria-label="Permalink to &quot;轻量标签&quot;">​</a></h3><p>最简单的标签，只是一个指向提交的指针：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.0.0</span></span></code></pre></div><h3 id="附注标签" tabindex="-1">附注标签 <a class="header-anchor" href="#附注标签" aria-label="Permalink to &quot;附注标签&quot;">​</a></h3><p>带说明信息的标签——推荐在生产发布时使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v2.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;正式发布 2.0 版本，包含支付模块和暗色模式&quot;</span></span></code></pre></div><p><code>-a</code> 表示 annotated（附注），<code>-m</code> 写说明。附注标签会记录打标签的人、时间、说明信息。</p><h3 id="给过去的提交打标签" tabindex="-1">给过去的提交打标签 <a class="header-anchor" href="#给过去的提交打标签" aria-label="Permalink to &quot;给过去的提交打标签&quot;">​</a></h3><p>忘了在发布那天打标签？找到那个 commit id，补上：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.5.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1.5 版本&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a1b2c3d</span></span></code></pre></div><h2 id="查看标签" tabindex="-1">查看标签 <a class="header-anchor" href="#查看标签" aria-label="Permalink to &quot;查看标签&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 列出所有标签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v2.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 查看标签详细信息（附注标签才能看到说明）</span></span></code></pre></div><h2 id="推送标签到远程" tabindex="-1">推送标签到远程 <a class="header-anchor" href="#推送标签到远程" aria-label="Permalink to &quot;推送标签到远程&quot;">​</a></h2><p>标签默认不会跟着 <code>git push</code> 一起推送到 GitHub。需要单独推送：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v2.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 推送单个标签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 推送所有标签</span></span></code></pre></div><h2 id="删除标签" tabindex="-1">删除标签 <a class="header-anchor" href="#删除标签" aria-label="Permalink to &quot;删除标签&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 删除本地标签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 删除远程标签</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>标签就是&quot;给重要的提交起个名字&quot;，简单但实用：</p><ol><li><strong>轻量标签</strong> — <code>git tag 名称</code>，快速指针</li><li><strong>附注标签</strong> — <code>git tag -a 名称 -m &quot;说明&quot;</code>，发布时用</li><li><strong>标签不会自动推送</strong> — 需要单独 <code>git push origin 标签名</code> 或 <code>git push --tags</code></li></ol><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>给当前版本打一个附注标签 <code>v1.0.0</code>，写好说明，用 <code>git show</code> 查看</li><li>再做一次提交，打一个轻量标签 <code>v1.1.0</code>，对比 <code>git show</code> 的输出差异</li><li>把两个标签推送到 GitHub，去仓库的 Releases 页面确认</li><li>删除本地标签 <code>v1.1.0</code>，再推送删除远程的 <code>v1.1.0</code></li></ol>`,29)])])}const F=a(l,[["render",n]]);export{c as __pageData,F as default};
